INSERT INTO `about_pages` (`id`, `who_we_are`, `banner_title`, `story_title`, `story_description`, `teacher_title`, `teacher_details`, `course_title`, `course_details`, `student_title`, `student_details`, `created_at`, `updated_at`, `image1`, `image2`, `image3`, `image4`, `show_testimonial`, `show_brand`, `show_become_instructor`, `total_teacher`, `total_student`, `total_courses`, `about_page_content_title`, `about_page_content_details`, `live_class_title`, `live_class_details`, `live_class_image`, `counter_bg`, `sponsor_title`, `sponsor_sub_title`, `lms_id`, `registered_students`, `questions_answers`, `quality_content`, `our_mission`, `our_vision`, `about_page_content_details2`) VALUES
(1, '{\"en\":\"Improving lives through Learning. We are always Inspired by the world and people us. Celebrating e-Learning excellence in Personal.\"}', '{\"en\":\"We are here to meet your demand and teach the most beneficial way for you in Personal.\"}', '{\"en\":\"Build your own library for your career and personal growth.\"}', '{\"en\":\"Our goal is to learn the next generation of creative professionals for a future in any industry. We offer course in most demanded industries. Whether begin to your journey on our courses website or choose the flexibility of video learning our courses are designed to help you along your path.\"}', '{\"en\":\"Most Involved Teachers\"}', '{\"en\":\"Key features are the ability to develop relationships with their students, patient, caring and kind knowledge offer learner engaging students of their.\"}', '{\"en\":\"High-Quality Course\"}', '{\"en\":\"Key features are the ability to develop relationships with their students, patient, caring and kind knowledge offer learner engaging students of their.\"}', '{\"en\":\"Large Selection of Courses\"}', '{\"en\":\"Key features are the ability to develop relationships with their students, patient, caring and kind knowledge offer learner engaging students of their.\"}', NULL, '2025-11-26 21:14:14', 'public/frontend/infixlmstheme/img/about/1.jpg', 'public/frontend/infixlmstheme/img/about/2.jpg', 'public/frontend/infixlmstheme/img/about/3.jpg', 'public/frontend/infixlmstheme/img/about/counter_bg.png', 1, 1, 1, '{\"en\":\"100+\"}', '{\"en\":\"200+\"}', '{\"en\":\"150+\"}', '{\"en\":\"Online Learning Platform\"}', '{\"en\":\"Areana ipsum dolor sit amet, consectetur adipiscing elit. Suspendisse varius enim eros elementum tristique. Duis cursus, mi quis viverra ornare, eros dolor interdum nulla, ut commodo diam libero vitae erat. Aenean faucibus nibh et justo cursus id rutrum lorem imperdiet. Nunc ut sem vitae risus tristique posuere.\"}', '{\"en\":\"Get Personal Learning Recommendations\"}', '{\"en\":\"Unlimited access to world-class learning from your laptop tablet, or phone. Join over 15,000+ students\"}', 'public/frontend/edume/img/lms_udemy/become_ins2.png', 'public/frontend/edume/img/about/counter_bg.png', '{\"en\":\"Trusted By\"}', '{\"en\":\"Thousands of students already add more focus to their work with InfixLMS.\"}', 1, NULL, NULL, NULL, NULL, NULL, NULL);
