(38, 'Payment_Done', '{\"en\":\"Payment Confirmation\"}', '{\"en\":\"Payment Confirmation\"}', '{\"en\":\"Hello {{name}}, <br\\/><br\\/>We are pleased to inform you that your payment of {{amount}} has been successfully processed. <br\\/>Transaction details are as follows:<br\\/>Transaction ID: {{txn_id}}<br\\/>Payment Date: {{payment_date}}<br\\/><br\\/>Thank you for choosing our services. If you have any questions or concerns, please feel free to contact us.<br\\/>\"}', '{\"name\":\"User Name\",\"amount\":\"Amount\",\"txn_id\":\"Txn ID\",\"payment_date_time\":\"Payment Date & Time\"}', 1, '2025-11-26 21:14:26', '2025-11-26 21:14:26', NULL, 0, 1, 0, NULL),
(39, 'Account_Deletion', '{\"en\":\"Account Deletion Confirmation\"}', '{\"en\":\"Account Deletion Confirmation\"}', '{\"en\":\"Hello {{name}}, <br\\/><br\\/>We regret to inform you that your account has been successfully deleted as per your request. <br\\/>If you have any feedback or would like to provide reasons for your decision, please feel free to reply to this email.<br\\/><br\\/>Thank you for being a part of our community. Should you decide to return in the future, we would be more than happy to assist you.<br\\/>\"}', '{\"name\":\"User Name\"}', 1, '2025-11-26 21:14:26', '2025-11-26 21:14:26', NULL, 0, 1, 0, NULL),
(40, 'Deposit_Unsuccessful', '{\"en\":\"Deposit Unsuccessful Notification\"}', '{\"en\":\"Deposit Unsuccessful\"}', '{\"en\":\"Hello {{name}}, <br\\/><br\\/>We regret to inform you that your recent attempt to deposit {{amount}} into your account was unsuccessful. <br\\/>Amount: {{amount}}<br\\/>Date and Time: {{date_time}}<br\\/><br\\/>If you require further assistance or have any questions, please contact our customer support team.<br\\/>\"}', '{\"name\":\"User Name\",\"amount\":\"Amount\",\"date_time\":\"Date and Time\"}', 1, '2025-11-26 21:14:26', '2025-11-26 21:14:26', NULL, 0, 1, 0, NULL),
(41, 'Deposit_Successful', '{\"en\":\"Deposit Successful Confirmation\"}', '{\"en\":\"Deposit Successful\"}', '{\"en\":\"Hello {{name}}, <br\\/><br\\/>We are pleased to inform you that your recent deposit of {{amount}} into your account has been successfully processed. <br\\/>Date and Time: {{date_time}}<br\\/><br\\/>If you have any questions or concerns, please do not hesitate to contact our customer support team.<br\\/>\"}', '{\"name\":\"User Name\",\"amount\":\"Amount\",\"date_time\":\"Date and Time\"}', 1, '2025-11-26 21:14:26', '2025-11-26 21:14:26', NULL, 0, 1, 0, NULL),
(42, 'Wallet_Credited', '{\"en\":\"Wallet Credited\"}', '{\"en\":\"Wallet Credited\"}', '{\"en\":\"Hello {{name}}, <br\\/><br\\/>Good news! Your wallet has been credited with {{amount}}. <br\\/>This transaction was processed on {{date_time}}.<br\\/><br\\/>If you have any inquiries or require assistance, please feel free to reach out to our customer support team.<br\\/>\"}', '{\"name\":\"User Name\",\"amount\":\"Amount\",\"date_time\":\"Date and Time\"}', 1, '2025-11-26 21:14:26', '2025-11-26 21:14:26', NULL, 0, 1, 0, NULL),
(43, 'New_Question', '{\"en\":\"New Question Inquiry\"}', '{\"en\":\"New Question Inquiry\"}', '{\"en\":\"Hello {{name}}, <br\\/><br\\/>Thank you for reaching out with your question. Your inquiry is important to us, and we appreciate your engagement with our services.<br\\/>Question Details:<br\\/>Question: {{question}}<br\\/>Date and Time: {{date_time}}<br\\/><br\\/>Our team will review your question and provide a detailed response as soon as possible. If you have any additional information to add, please reply to this email.<br\\/><br\\/>Thank you for your patience.<br\\/>{{footer}}\"}', '{\"name\":\"User Name\",\"question\":\"User Question\",\"date_time\":\"Date and Time\"}', 1, '2025-11-26 21:14:26', '2025-11-26 21:14:26', NULL, 0, 1, 0, NULL),
(44, 'New_Question_Reply', '{\"en\":\"Question Reply\"}', '{\"en\":\"Question Reply\"}', '{\"en\":\"Hello {{name}}, <br\\/><br\\/>Thank you for your question. We appreciate your engagement with our services.<br\\/>Your Question:<br\\/>{{question}}<br\\/><br\\/>Our Response:<br\\/>{{reply}}<br\\/>Date and Time: {{date_time}}<br\\/><br\\/>If you have any further questions or need additional assistance, please feel free to reach out. We\'re here to help!<br\\/><br\\/>Thank you for choosing our services.<br\\/>{{footer}}\"}', '{\"name\":\"User Name\",\"question\":\"User Question\",\"reply\":\"Answer\",\"date_time\":\"Date and Time\"}', 1, '2025-11-26 21:14:26', '2025-11-26 21:14:26', NULL, 0, 1, 0, NULL),
(45, 'EmailVerificationOTP', 'Send Email Verification OTP Notification', 'Email Verification OTP Notification', '\n    <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css\">\n    <style>\n\n         .social_links {\n            background: #F4F4F8;\n            padding: 15px;\n            margin: 30px 0 30px 0;\n        }\n\n        .social_links a {\n            display: inline-block;\n            font-size: 15px;\n            color: #252B33;\n            padding: 5px;\n        }\n\n\n    </style>\n\n    <div class=\"\">\n    <div style=\"color: rgb(255, 255, 255); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; text-align: center; background-color: rgb(65, 80, 148); padding: 30px; border-top-left-radius: 3px; border-top-right-radius: 3px; margin: 0px;\"><h1 style=\"margin: 20px 0px 10px; font-family: &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: 500; line-height: 1.1; color: inherit; font-size: 36px;\">\n    Send Email Verification OTP Notification\n\n    </h1></div><div style=\"color: rgb(0, 0, 0); font-family: &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; padding: 20px;\">\n    <p style=\"color: rgb(85, 85, 85);\"><br></p>\n    <p style=\"color: rgb(85, 85, 85);\">Hello {{name}}, Your otp Code is {{otp}} <br/>{{footer}}</p></div>\n    </div>\n\n    <div class=\"email_invite_wrapper\" style=\"text-align: center\">\n\n\n        <div class=\"social_links\">\n            <a href=\"https://twitter.com/codetheme\"> <i class=\"fab fa-facebook-f\"></i> </a>\n            <a href=\"https://codecanyon.net/user/codethemes/portfolio\"><i class=\"fas fa-code\"></i> </a>\n            <a href=\"https://twitter.com/codetheme\" target=\"_blank\"> <i class=\"fab fa-twitter\"></i> </a>\n            <a href=\"https://dribbble.com/codethemes\"> <i class=\"fab fa-dribbble\"></i></a>\n        </div>\n    </div>\n\n    ', '{\"ot