INSERT INTO `online_quizzes` (`id`, `title`, `percentage`, `instruction`, `status`, `is_taken`, `is_closed`, `is_waiting`, `is_running`, `active_status`, `created_at`, `updated_at`, `category_id`, `sub_category_id`, `course_id`, `created_by`, `updated_by`, `random_question`, `question_time_type`, `question_time`, `question_review`, `show_result_each_submit`, `multiple_attend`, `lms_id`, `group_id`, `show_ans_with_explanation`, `losing_focus_acceptance_number`, `losing_type`, `show_ans_sheet`, `show_score_result`, `multiple_attend_count`, `default_setting`, `show_correct_ans_in_ans_sheet`, `show_only_wrong_ans_in_ans_sheet`, `show_total_correct_answer`, `total_questions`, `total_marks`) VALUES
(3, '{\"en\":\"Python MCQ\"}', 70, '{\"en\":\"Test your understanding of  Python concepts with this beginner-friendly quiz. These questions cover essential topics such as syntax, variables, data types, and common functions—perfect for learners who are just starting their Python journey.\"}', 1, 0, 0, 0, 0, 1, '2025-12-08 19:16:40', '2025-12-08 20:35:34', 14, 0, NULL, 1, 1, 0, 0, 1, 1, 1, 1, 1, 2, 0, 0, 1, 1, 1, 0, 0, 1, 0, 0, 10, 100),
(4, '{\"en\":\"HTML\"}', 70, '{\"en\":\"This quiz is designed to test your understanding of the fundamental concepts of HTML, the core language used to build web pages. You will answer questions related to HTML tags, attributes, document structure, and basic formatting elements. Completing this quiz will help reinforce your knowledge and ensure you have a strong foundation for further web development learning.\"}', 1, 0, 0, 0, 0, 1, '2025-12-08 20:19:21', '2025-12-08 20:44:00', 14, 0, NULL, 1, 1, 0, 0, 1, 1, 1, 1, 1, 3, 0, 0, 1, 1, 1, 0, 0, 1, 0, 0, 10, 10),
(5, '{\"en\":\"cyber\"}', 70, '{\"en\":\"This quiz tests your basic understanding of common cyber threats and online safety. It is designed for beginners and helps you learn how to recognize and avoid digital risks.\"}', 1, 0, 0, 0, 0, 1, '2025-12-08 20:24:56', '2025-12-08 20:35:11', 16, 0, NULL, 1, 1, 0, 0, 1, 1, 1, 1, 1, NULL, 0, 0, 1, 1, 1, 0, 0, 1, 0, 0, 3, 30),
(6, '{\"en\":\"CSS\"}', 70, '{\"en\":\"This quiz assesses your understanding of Cascading Style Sheets (CSS), the language used to style and visually enhance web pages. It covers fundamental concepts such as selectors, properties, colors, typography, layout, and the box model. By completing this quiz, you will strengthen your knowledge of how CSS controls the appearance and presentation of HTML content.\"}', 1, 0, 0, 0, 0, 1, '2025-12-08 20:34:56', '2025-12-08 20:51:38', 14, 0, NULL, 1, 1, 0, 0, 1, 1, 1, 1, 1, 4, 0, 0, 1, 1, 1, 0, 0, 1, 0, 0, 10, 10),
(7, '{\"en\":\"JavaScript Quiz\"}', 70, '{\"en\":\"This quiz evaluates your understanding of JavaScript, the programming language that adds interactivity and dynamic behavior to web pages. It covers essential concepts such as variables, data types, operators, functions, events, and basic DOM manipulation. Completing this quiz will help strengthen your foundation in JavaScript and prepare you for more advanced programming topics.\"}', 1, 0, 0, 0, 0, 1, '2025-12-08 20:49:38', '2025-12-08 20:53:45', 14, 0, NULL, 1, 1, 0, 0, 1, 1, 1, 1, 1, 5, 0, 0, 1, 1, 1, 0, 0, 1, 0, 0, 10, 10),
(8, '{\"en\":\"JAVA\"}', 70, '{\"en\":\"This quiz evaluates your understanding of Java, a powerful object-oriented programming language widely used for application development. The questions cover essential concepts such as variables, data types, operators, control statements, classes, objects, and basic OOP principles. Completing this quiz will help reinforce your foundational Java knowledge and prepare you for more advanced programming topics.\"}', 1, 0, 0, 0, 0, 1, '2025-12-08 21:06:43', '2025-12-08 21:07:14', 14, 0, NULL, 1, 1, 0, 0, 1, 1, 1, 1, 1, 6, 0, 0, 1, 1, 1, 0, 0, 1, 0, 0, 10, 10);
